class Solution:
    def maximumGood(self, S):
        n, ans = len(S), 0
        def valid(cur):
            for i in range(n):
                if cur[i]:
                    for j in range(n):
                        if S[i][j] != 2 and S[i][j] != cur[j]: return False
            return True;
        def dfs(cur, i, cnt):
            nonlocal ans
            if i == n:
                if valid(cur): ans = max(ans, cnt)
                return
            cur.append(0)
            dfs(cur, i+1, cnt)
            cur[-1] = 1
            dfs(cur, i+1, cnt+1)
            cur.pop()

        dfs([], 0, 0)
        return ans

class Solution:
    def maximumGood(self, statements):
        def check(mask):
            return all(((mask>>j)&1) == statements[i][j]
                       for i in range(len(statements)) if (mask>>i)&1 
                       for j in range(len(statements[i])) if statements[i][j] != 2)

        def popcount(x):
            result = 0
            while x:
                x &= x-1
                result += 1
            return result

        result = 0
        for mask in range(1<<len(statements)):
            if check(mask):
                result = max(result, popcount(mask))
        return result

